"""Retention proposals and legal holds for GDPR retention management."""

import uuid

from django.conf import settings
from django.db import models
from django.utils import timezone
from django.utils.translation import gettext_lazy as _

from core.models.managers import FacilityScopedManager


class RetentionProposal(models.Model):
    """Deletion proposal generated by the retention run, awaiting approval."""

    class Status(models.TextChoices):
        PENDING = "pending", _("Ausstehend")
        APPROVED = "approved", _("Freigegeben")
        HELD = "held", _("Legal Hold")
        DEFERRED = "deferred", _("Zurückgestellt")
        REJECTED = "rejected", _("Abgelehnt")

    class TargetType(models.TextChoices):
        EVENT = "Event", _("Event")

    objects = FacilityScopedManager()

    id = models.UUIDField(primary_key=True, default=uuid.uuid4, editable=False)
    facility = models.ForeignKey(
        "core.Facility",
        on_delete=models.CASCADE,
        related_name="retention_proposals",
        verbose_name=_("Einrichtung"),
    )
    target_type = models.CharField(
        max_length=100,
        choices=TargetType.choices,
        verbose_name=_("Zieltyp"),
    )
    target_id = models.UUIDField(verbose_name=_("Ziel-ID"))
    proposed_by = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        on_delete=models.SET_NULL,
        null=True,
        blank=True,
        related_name="retention_proposals",
        verbose_name=_("Vorgeschlagen von"),
    )
    first_approved_by = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        on_delete=models.SET_NULL,
        null=True,
        blank=True,
        related_name="first_approved_retention_proposals",
        verbose_name=_("Erste Freigabe durch"),
    )
    first_approved_at = models.DateTimeField(null=True, blank=True, verbose_name=_("Erste Freigabe am"))
    approved_by = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        on_delete=models.SET_NULL,
        null=True,
        blank=True,
        related_name="approved_retention_proposals",
        verbose_name=_("Freigegeben von"),
    )
    approved_at = models.DateTimeField(null=True, blank=True, verbose_name=_("Freigegeben am"))
    auto_approved_at = models.DateTimeField(
        null=True, blank=True, editable=False, verbose_name=_("Automatisch freigegeben am")
    )
    rejected_at = models.DateTimeField(null=True, blank=True, verbose_name=_("Abgelehnt am"))
    proposed_at = models.DateTimeField(auto_now_add=True, verbose_name=_("Vorgeschlagen am"))
    deletion_due_at = models.DateField(verbose_name=_("Löschfrist"))
    status = models.CharField(
        max_length=20,
        choices=Status.choices,
        default=Status.PENDING,
        verbose_name=_("Status"),
    )
    details = models.JSONField(default=dict, blank=True, verbose_name=_("Details"))
    retention_category = models.CharField(
        max_length=50,
        verbose_name=_("Kategorie"),
        help_text=_("anonymous, identified, qualified oder document_type"),
    )
    deferred_until = models.DateField(
        null=True,
        blank=True,
        verbose_name=_("Wiedervorlage am"),
        help_text=_("Datum, ab dem ein zurückgestellter Vorschlag wieder vorgelegt wird."),
    )
    defer_count = models.PositiveIntegerField(
        default=0,
        verbose_name=_("Anzahl Zurückstellungen"),
        help_text=_("Wie oft wurde der Vorschlag bereits zurückgestellt."),
    )

    class Meta:
        verbose_name = _("Löschvorschlag")
        verbose_name_plural = _("Löschvorschläge")
        ordering = ["deletion_due_at"]
        constraints = [
            models.CheckConstraint(
                condition=~models.Q(first_approved_by=models.F("approved_by")),
                name="retention_proposal_distinct_approvers",
            ),
            models.UniqueConstraint(
                fields=["facility", "target_type", "target_id"],
                condition=models.Q(status__in=["pending", "held", "deferred"]),
                name="unique_active_retention_proposal",
            ),
        ]

    @property
    def has_approval_evidence(self):
        """Require two documented reviewers or the explicit automatic exception."""
        if self.status != self.Status.APPROVED or self.approved_at is None:
            return False
        if self.auto_approved_at is not None:
            return self.approved_by_id is None and self.auto_approved_at == self.approved_at
        return (
            self.first_approved_by_id is not None
            and self.approved_by_id is not None
            and self.first_approved_by_id != self.approved_by_id
            and self.first_approved_at is not None
            and self.first_approved_at <= self.approved_at
            and self.proposed_by_id not in (self.first_approved_by_id, self.approved_by_id)
        )

    def __str__(self):
        return f"Löschvorschlag {self.target_type} ({self.get_status_display()})"


class LegalHold(models.Model):
    """Explicit postponement of deletion for a specific record."""

    objects = FacilityScopedManager()

    id = models.UUIDField(primary_key=True, default=uuid.uuid4, editable=False)
    facility = models.ForeignKey(
        "core.Facility",
        on_delete=models.CASCADE,
        related_name="legal_holds",
        verbose_name=_("Einrichtung"),
    )
    target_type = models.CharField(max_length=100, verbose_name=_("Zieltyp"))
    target_id = models.UUIDField(verbose_name=_("Ziel-ID"))
    reason = models.TextField(verbose_name=_("Begründung"))
    expires_at = models.DateField(
        null=True,
        blank=True,
        verbose_name=_("Ablaufdatum"),
    )
    created_by = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        # Refs #1347 (DAT-04): PROTECT statt CASCADE — ein Legal Hold ist ein
        # Compliance-Objekt (Nachweis einer Aufbewahrungspflicht/Spoliation-
        # Schutz). Eine harte Loeschung des Erstellers darf den Hold nicht
        # mitreissen; ``user.delete()`` muss stattdessen mit
        # ``ProtectedError`` abbrechen, solange aktive Holds existieren.
        on_delete=models.PROTECT,
        related_name="legal_holds",
        verbose_name=_("Erstellt von"),
    )
    created_at = models.DateTimeField(auto_now_add=True, verbose_name=_("Erstellt am"))
    dismissed_at = models.DateTimeField(
        null=True,
        blank=True,
        verbose_name=_("Aufgehoben am"),
    )
    dismissed_by = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        on_delete=models.SET_NULL,
        null=True,
        blank=True,
        related_name="dismissed_holds",
        verbose_name=_("Aufgehoben von"),
    )

    @property
    def is_active(self):
        """A hold is active if not dismissed and not expired.

        Uses ``timezone.localdate()`` (Europe/Berlin) rather than the naive,
        server-local ``date.today()`` so the active/expired boundary does not
        shift by a day near midnight (UTC vs. Berlin). Stays in lockstep with
        the dashboard SQL filter in ``core.services.dashboard.main`` (#1191).
        """
        if self.dismissed_at:
            return False
        return not (self.expires_at and self.expires_at < timezone.localdate())

    class Meta:
        verbose_name = _("Legal Hold")
        verbose_name_plural = _("Legal Holds")
        ordering = ["-created_at"]
        constraints = [
            # Refs #1347 (DAT-02): verhindert doppelte AKTIVE Holds auf
            # demselben Ziel — analog ``unique_active_retention_proposal``/
            # ``unique_pending_deletion_request``. "Aktiv" wird hier ueber
            # ``dismissed_at IS NULL`` gefasst (nicht zusaetzlich ueber
            # ``expires_at``, da ein DB-Constraint-Predicate IMMUTABLE sein
            # muss und ``CURRENT_DATE`` das nicht ist) — ein bereits
            # abgelaufener, aber noch nicht aufgehobener Hold blockiert einen
            # neuen Hold auf dasselbe Ziel bewusst weiterhin; er muss explizit
            # aufgehoben (dismissed) werden.
            models.UniqueConstraint(
                fields=["facility", "target_type", "target_id"],
                condition=models.Q(dismissed_at__isnull=True),
                name="unique_active_legal_hold",
            ),
        ]

    def __str__(self):
        status = _("aktiv") if self.is_active else _("inaktiv")
        return f"Legal Hold {self.target_type} ({status})"
